aarch64-linux-gnu-nm /tmp/mono_debug.so 2>/dev/null | awk '{print $1, $3}' | sort | awk -v a1="0x2f4b20" -v a2="0x2f4c84" '
BEGIN { addr1 = strtonum(a1); addr2 = strtonum(a2) }
{ val = strtonum("0x"$1); names[NR] = $2; addrs[NR] = val }
END {
