arguments.command:
aarch64-linux-gnu-nm /tmp/mono_debug.so 2>/dev/null | sort | awk '
{addrs[NR] = strtonum("0x"$1); names[NR] = $3; types[NR] = $2}
END {
  targets[1] = 0x2f4b20; targets[2] = 0x2f4c84
  for (t=1; t<=2; t++) {
    best = 0; bestname = "?"
    for (i=1; i<=NR; i++) {
      if (addrs[i] <= targets[t] && addrs[i] > best) { best = addrs[i]; bestname = names[i]; besttype = types[i] }
    }
    printf "0x%x -> %s (type=%s) + 0x%x\n", targets[t], bestname, besttype, targets[t]-best
  }
}'

